(function(){var d={"book": {"chapters": [{"blocks": [{"ent": "u:f6b6c3b5b88d82b2"}, {"ent": "u:003026c34fd830a1"}, {"ent": "u:7dc798f376292a99"}, {"ent": "u:cbd9a2033c967fda"}, {"ent": "u:f043980538821102"}, {"ent": "u:19ec8b8affb568a4"}, {"ent": "u:00454359ff014743"}, {"ent": "u:2c9dfdf12887d145"}, {"ent": "u:487624d935315da6"}, {"ent": "u:06f5bb85e1f7e741"}, {"ent": "u:a2655b3c8c278843"}, {"ent": "u:afd51e0dc639b17b"}, {"ent": "u:1c538592218e6557"}, {"ent": "u:4e26d714a746583f"}, {"ent": "u:41764fa5514ba217"}, {"ent": "u:4204367a3f648279"}, {"ent": "u:eecc69c02dfcbdb0"}, {"ent": "u:0d47f1b771c62981"}, {"ent": "u:31cfda6b0ea88027"}, {"ent": "u:3c3e5f8e920d7ace"}, {"ent": "u:4ba666e8f78cb2ed"}, {"ent": "u:079bec650fac265a"}, {"ent": "u:b5963f0d1583f44b"}, {"ent": "u:a255e5478757798e"}, {"ent": "u:1837e2f66b34b769"}, {"ent": "u:1cf10402d33c7d3a"}, {"ent": "u:3e1d7c168c36f9a0"}, {"ent": "u:b9d3096aa6fa952b"}, {"ent": "u:2f9d07d8a842289d"}, {"ent": "u:55a665cfbca63784"}, {"ent": "u:cf6728b8518c8853"}], "container": "EXTENSION", "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "kind": "ttrpg", "module": "L5R5e_GM_Screen_Reference", "moduleExtends": "L5R5e_Core_Character", "name": "Legend of the Five Rings 5th Edition - GM Screen Quick Reference", "page": null, "roots": ["u:f6b6c3b5b88d82b2", "u:003026c34fd830a1", "u:7dc798f376292a99", "u:cbd9a2033c967fda", "u:f043980538821102", "u:19ec8b8affb568a4", "u:00454359ff014743", "u:2c9dfdf12887d145", "u:487624d935315da6", "u:06f5bb85e1f7e741", "u:a2655b3c8c278843", "u:afd51e0dc639b17b", "u:1c538592218e6557", "u:4e26d714a746583f", "u:41764fa5514ba217", "u:4204367a3f648279", "u:eecc69c02dfcbdb0", "u:0d47f1b771c62981", "u:31cfda6b0ea88027", "u:3c3e5f8e920d7ace", "u:4ba666e8f78cb2ed", "u:079bec650fac265a", "u:b5963f0d1583f44b", "u:a255e5478757798e", "u:1837e2f66b34b769", "u:1cf10402d33c7d3a", "u:3e1d7c168c36f9a0", "u:b9d3096aa6fa952b", "u:2f9d07d8a842289d", "u:55a665cfbca63784", "u:cf6728b8518c8853"]}], "entities": ["u:f6b6c3b5b88d82b2", "u:003026c34fd830a1", "u:7dc798f376292a99", "u:cbd9a2033c967fda", "u:f043980538821102", "u:19ec8b8affb568a4", "u:00454359ff014743", "u:2c9dfdf12887d145", "u:487624d935315da6", "u:06f5bb85e1f7e741", "u:a2655b3c8c278843", "u:afd51e0dc639b17b", "u:1c538592218e6557", "u:4e26d714a746583f", "u:41764fa5514ba217", "u:4204367a3f648279", "u:eecc69c02dfcbdb0", "u:0d47f1b771c62981", "u:31cfda6b0ea88027", "u:3c3e5f8e920d7ace", "u:4ba666e8f78cb2ed", "u:079bec650fac265a", "u:b5963f0d1583f44b", "u:a255e5478757798e", "u:1837e2f66b34b769", "u:1cf10402d33c7d3a", "u:3e1d7c168c36f9a0", "u:b9d3096aa6fa952b", "u:2f9d07d8a842289d", "u:55a665cfbca63784", "u:cf6728b8518c8853"], "id": "gm-screen", "kind": "book", "label": "GM Screen"}, "entities": {"u:003026c34fd830a1": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:003026c34fd830a1", "name": "Five Rings Reference", "parent": null, "rules": [{"id": "#L5RGS02lM3nO5pQ7rS9tU1v", "text": "ref_five_rings_approaches \"The Five Rings: Air: A graceful, cunning, and precise approach; subtle and nuanced.\\n\\nEarth: A steady, thorough, and grounded approach; cautious and reliable.\\n\\nFire: A ferocious, direct, and inventive approach; explosive and intense.\\n\\nWater: An adaptable, powerful, and perceptive approach; balanced and reversible.\\n\\nVoid: A centered, unflinching approach; enlightened and accepting.\""}], "slot": null, "synthetic": true}, "u:00454359ff014743": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:00454359ff014743", "name": "Void Points Reference", "parent": null, "rules": [{"id": "#L5RGS07oP8qR0sT2uV4wX6y", "text": "ref_void_points_spending \"Spending: Seize the Moment: While making a check, may spend 1 Void point to roll one additional Ring die and keep one additional die.\\n\\nShattering Parry: When resisting a critical strike, may spend 1 Void point to intercept the attack with a weapon to increase survival chance, potentially sacrificing the weapon.\""}, {"id": "#L5RGS08zA9bC1dE3fG5hI7j", "text": "ref_void_points_gaining \"Gaining: After failing a check on which one adversity was resolved (page 22).\\n\\nOnce per scene, after an anxiety causes strife to increase (page 22).\\n\\nAfter choosing to be affected by a complication that the GM (or player) introduced into the scene (page 37).\\n\\nAfter the GM conceals the TN of a check from the players.\""}], "slot": null, "synthetic": true}, "u:06f5bb85e1f7e741": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:06f5bb85e1f7e741", "name": "Sample TNs Reference", "parent": null, "rules": [{"id": "#L5RGS12rS3tU5vW7xY9zA1b", "text": "ref_sample_target_numbers \"Sample Tasks and Target Numbers: TN 0\\n\\nA simple task (carrying a normal weight or remembering a friend's name). Generally, such a task shouldn't require a check.\\n\\nTN 1\\n\\nAn easy task (carrying half one's weight or finding a misplaced item).\\n\\nTN 2\\n\\nAn average task (jumping a ten-foot ditch or recognizing someone in disguise).\\n\\nTN 3\\n\\nA difficult task (scaling a cliff without rope or finding a well-hidden object).\\n\\nTN 4\\n\\nA very hard task (diving safely from the top of a waterfall or recalling someone's exact words years later).\\n\\nTN 5\\n\\nAn extremely hard task (stirring a demoralized army to action or hurling someone using only one hand).\\n\\nTN 6\\n\\nAn extraordinary task (solving a crime using only a very subtle clue or felling a tree with a single blow).\\n\\nTN 7\\n\\nA heroic task (outwrestling a troll or naming all of one's ancestors in order).\\n\\nTN 8+\\n\\nA legendary task (shattering stone with one's bare hands or outwitting a Fortune).\""}], "slot": null, "synthetic": true}, "u:079bec650fac265a": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:079bec650fac265a", "name": "Condition: Wounded", "parent": null, "rules": [{"id": "#L5RGS24tU5vW7xY9zA1bC3d", "text": "ref_condition_wounded_lightly \"Lightly Wounded [One Ring]: Effects: Increase the TN of checks with the affected ring by 1.\\n\\nIf the character suffers the Severely Wounded condition for the same ring, remove this condition.\\n\\nIf the character would suffer the Lightly Wounded condition again for the same ring, they remove it and suffer the Severely Wounded condition for that ring.\""}, {"id": "#L5RGS25eF6gH8iJ0kL2mN4o", "text": "ref_condition_wounded_severely \"Severely Wounded [One Ring]: Effects: Increase the TN of checks with the affected ring by 3.\\n\\nIf the character suffers the Lightly Wounded or Severely Wounded condition for the same ring, they remove that condition and suffer the effects of a severity 8 critical strike for that ring as if they had failed the check to resist it (see page 270).\""}, {"id": "#ukFXm8UNa5141MC8Z6GNgy", "text": "ref_condition_wounded \"Wounded: Effects: This condition has two forms: Lightly Wounded and Severely Wounded.\\n\\nRemoved When: A character makes a TN 4 Medicine (Water) check as a downtime activity. If they succeed, the wounded character removes Lightly Wounded or reduces Severely Wounded to Lightly Wounded. This check can be attempted once per wounded ring per week. Characters can also heal through bed rest (page 273).\""}], "slot": null, "synthetic": true}, "u:0d47f1b771c62981": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:0d47f1b771c62981", "name": "Condition: Disoriented", "parent": null, "rules": [{"id": "#L5RGS20bC1dE3fG5hI7jK9l", "text": "ref_condition_disoriented \"Disoriented: Effects: Increase TN of Movement and Support action checks by 2.\\n\\nRemoved When: At the end of turn, if the character did not perform a Movement or Support action.\""}], "slot": null, "synthetic": true}, "u:1837e2f66b34b769": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:1837e2f66b34b769", "name": "Item Quality: Damaged", "parent": null, "rules": [{"id": "#L5RGS28lM9nO1pQ3rS5tU7v", "text": "ref_quality_damaged \"Damaged: If a weapon or tool becomes Damaged, increase the TN of checks to use it by 1.\\n\\nIf armor becomes Damaged, reduce all resistances it provides by 2 (to a minimum of 0).\\n\\nIf a Damaged item becomes Damaged again, it loses Damaged and becomes Destroyed instead.\""}], "slot": null, "synthetic": true}, "u:19ec8b8affb568a4": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:19ec8b8affb568a4", "name": "Initiative Reference", "parent": null, "rules": [{"id": "#L5RGS06dE7fG9hI1jK3lM5n", "text": "ref_initiative_by_conflict_type \"Initiative: Conflict type determines check to make:\\n\\nIntrigue: TN 1 Sentiment check.\\n\\nDuel: TN 1 Meditation check.\\n\\nSkirmish: TN 1 Tactics check.\\n\\nMass Battle: TN 1 Command check.\\n\\nA character can use any ring they choose for this check. Add 1 plus number of bonus successes on check to either focus or vigilance, depending on preparedness for the conflict, to determine final initiative value.\\n\\nIf ready for the conflict: use focus attribute.\\n\\nIf not ready or surprised: use vigilance attribute.\\n\\nThe character then enters the stance matching the ring used for the check.\""}], "slot": null, "synthetic": true}, "u:1c538592218e6557": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:1c538592218e6557", "name": "Commonly Referenced Rules Index", "parent": null, "rules": [{"id": "#L5RGS15yZ6aB8cD0eF2gH4i", "text": "commonly_referenced_social_attributes \"Social Attributes: Ninjō page 38\\n\\nGiri page 39\\n\\nHonor page 300\\n\\nGlory page 304\\n\\nStatus page 305\""}, {"id": "#OrtLBa6F72W0tsNbPrAeve", "text": "commonly_referenced_alternate_check_types \"Alternate Check Types: Assistance page 26\\n\\nCompetitive page 26\\n\\nInvestigations page 170\\n\\nResisting page 26\""}, {"id": "#WIYuppzPzAcUVL2IoXlzWC", "text": "commonly_referenced_conflict_types \"Conflict Types: Intrigues page 254\\n\\nDuels page 258\\n\\nSkirmishes page 262\""}, {"id": "#sSZaMwkGko5A892NWxskKN", "text": "commonly_referenced_harm_and_terrain \"Harm and Terrain: Fatigue page 269\\n\\nFalling Damage page 269\\n\\nTerrain Qualities page 267\""}, {"id": "#IfZpSM4zbEfGNGO6dln4Iq", "text": "commonly_referenced_exceeding_composure \"Exceeding Composure: Becoming Compromised page 30\\n\\nExamples of Unmasking page 31\""}], "slot": null, "synthetic": true}, "u:1cf10402d33c7d3a": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:1cf10402d33c7d3a", "name": "Item Quality: Prepare", "parent": null, "rules": [{"id": "#L5RGS29wX0yZ2aB4cD6eF8g", "text": "ref_quality_prepare \"Prepare: After you use this item, you cannot use it again until it has been prepared. As a Support action, while it is readied, prepares this item for use.\""}], "slot": null, "synthetic": true}, "u:2c9dfdf12887d145": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:2c9dfdf12887d145", "name": "Advantages and Disadvantages Reference", "parent": null, "rules": [{"id": "#L5RGS09kL0mN2oP4qR6sT8u", "text": "ref_advantages_distinctions_passions \"Advantages: Distinctions: When making a check to which distinction applies, may reroll up to 2 dice.\\n\\nPassions: When making a check to which passion applies, remove 3 strife.\""}, {"id": "#L5RGS10vW1xY3zA5bC7dE9f", "text": "ref_disadvantages_adversities_anxieties \"Disadvantages: Adversities: When making a check to which adversity applies, must reroll up to 2 dice with (su) or (ex). Regain 1 Void point if failed check.\\n\\nAnxieties: When making a check to which anxiety applies, receive 2 strife. Regain 1 Void point if this is the first occurrence in the scene.\""}], "slot": null, "synthetic": true}, "u:2f9d07d8a842289d": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:2f9d07d8a842289d", "name": "Item Quality: Snaring", "parent": null, "rules": [{"id": "#L5RGS32dE3fG5hI7jK9lM1n", "text": "ref_quality_snaring \"Snaring: When performing an Attack action with a Snaring weapon, you may spend (op) as follows:\\n\\n(op)+: One target of the attack with vigilance lower than or equal to the (op) spent this way suffers the Immobilized condition.\""}], "slot": null, "synthetic": true}, "u:31cfda6b0ea88027": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:31cfda6b0ea88027", "name": "Condition: Dying [X Rounds]", "parent": null, "rules": [{"id": "#L5RGS21mN2oP4qR6sT8uV0w", "text": "ref_condition_dying \"Dying [X Rounds]: Effects: After X number of rounds (or an amount of narrative time has passed, the character perishes at the end of their next turn (or after completing one task in a narrative scene).\\n\\nRemoved When: A character at range 0–1 of a Dying character makes a TN 4 Medicine (Air) check as a Support action to remove it. If they fail, reduce the number of rounds remaining for the Dying condition by their shortfall.\""}], "slot": null, "synthetic": true}, "u:3c3e5f8e920d7ace": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:3c3e5f8e920d7ace", "name": "Condition: Incapacitated", "parent": null, "rules": [{"id": "#L5RGS22xY3zA5bC7dE9fG1h", "text": "ref_condition_incapacitated \"Incapacitated: Effects: Cannot perform actions that require checks and cannot defend against damage. Critical strikes inflict the Unconscious condition in addition to any other effects.\\n\\nRemoved When: Fatigue is reduced to a value lower than or equal to the character's endurance.\""}], "slot": null, "synthetic": true}, "u:3e1d7c168c36f9a0": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:3e1d7c168c36f9a0", "name": "Item Quality: Razor-Edged", "parent": null, "rules": [{"id": "#L5RGS30hI1jK3lM5nO7pQ9r", "text": "ref_quality_razor_edged \"Razor-Edged: When you succeed at an Attack action check that deals damage to a target using a Razor-Edged item, if the damage dealt is reduced to 0 before they defend, this item becomes Damaged.\\n\\nWhen using a Razor-Edged weapon, you may spend (op)+ to treat the deadliness of this weapon as 1 higher per (op) spent this way.\""}], "slot": null, "synthetic": true}, "u:41764fa5514ba217": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:41764fa5514ba217", "name": "Condition: Bleeding", "parent": null, "rules": [{"id": "#L5RGS17uV8wX0yZ2aB4cD6e", "text": "ref_condition_bleeding \"Bleeding: Effects: When keeping (st) results on dice, the character suffers the same amount of physical damage, ignoring their resistance. Such damage inflicts a critical strike with severity equal to the character's current fatigue.\\n\\nRemoved When: A character at range 0–1 of a Bleeding character makes a TN 2 Medicine (Earth) check as a Support action to remove it.\""}], "slot": null, "synthetic": true}, "u:4204367a3f648279": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:4204367a3f648279", "name": "Condition: Compromised", "parent": null, "rules": [{"id": "#L5RGS18fG9hI1jK3lM5nO7p", "text": "ref_condition_compromised \"Compromised: Effects: Cannot keep dice with (st) symbols (to a possible minimum of 0 kept dice). Their vigilance counts as 1.\\n\\nRemoved When: Strife is reduced to a value lower than or equal to their composure.\""}], "slot": null, "synthetic": true}, "u:487624d935315da6": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:487624d935315da6", "name": "Range Bands Reference", "parent": null, "props": [{"dtype": "STRING", "name": "Range 0", "value": "Touch (1-2 feet)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 1", "value": "Sword (1-2 yards)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 2", "value": "Spear (3-4 yards)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 3", "value": "Throw (5-10 yards)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 4", "value": "Bow (11-100 yards)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 5", "value": "Volley (100+ yards)", "vk": "scalar"}, {"dtype": "STRING", "name": "Range 6", "value": "Sight (several hundred yards)", "vk": "scalar"}], "slot": null, "synthetic": true}, "u:4ba666e8f78cb2ed": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:4ba666e8f78cb2ed", "name": "Condition: Prone", "parent": null, "rules": [{"id": "#L5RGS23iJ4kL6mN8oP0qR2s", "text": "ref_condition_prone \"Prone: Effects: Can move a maximum of 1 range band.\\n\\nRemoved When: (If desired) at the end of their turn, if the character did not perform a Movement action.\""}], "slot": null, "synthetic": true}, "u:4e26d714a746583f": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:4e26d714a746583f", "name": "Condition: Afflicted", "parent": null, "rules": [{"id": "#L5RGS16jK7lM9nO1pQ3rS5t", "text": "ref_condition_afflicted \"Afflicted: Effects: The character's vigilance counts as 1, and when they make a check the GM may alter one kept (ring) to a face set to (op) (st).\\n\\nRemoved When: A ritual such as Cleansing Rite (see page 212) or another ability cleanses it.\""}], "slot": null, "synthetic": true}, "u:55a665cfbca63784": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:55a665cfbca63784", "name": "Item Quality: Unholy", "parent": null, "rules": [{"id": "#L5RGS33oP4qR6sT8uV0wX2y", "text": "ref_quality_unholy \"Unholy: After a character suffers a critical strike from an Unholy weapon, they suffer the Afflicted condition.\\n\\nAt the end of each scene in which you use an Unholy item, you suffer the Afflicted condition.\\n\\nUnholy weapons ignore all resistances possessed by Otherworldly beings.\""}], "slot": null, "synthetic": true}, "u:7dc798f376292a99": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:7dc798f376292a99", "name": "Making a Check Reference", "parent": null, "rules": [{"id": "#L5RGS03wX4yZ6aB8cD0eF2g", "text": "ref_making_a_check_procedure \"Making a Check: 1. GM sets skill, approach, and TN based on player intention.\\n\\n2. Player assembles dice pool of Ring dice ((ring)) and Skill dice ((skill)).\\n\\n3. Player rolls dice and keeps dice equal to Ring used.\\n\\n4. Resolve dice and determine outcome:\\n\\n(ex): For each (ex), roll one additional die of the same type as the one showing the (ex). After rolling, choose whether it will be kept or dropped. If kept, its effects are added to those from the other dice.\\n\\n(st): For each (st), the character receives 1 strife.\\n\\n(op): The player may spend 1 or more (op) to resolve opportunities.\\n\\n(su): If the sum total of (su) and (ex) results equals or exceeds the TN, the check is successful. Any (su) beyond the ones needed to reach the TN are bonus successes.\""}], "slot": null, "synthetic": true}, "u:a255e5478757798e": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:a255e5478757798e", "name": "Item Quality: Cumbersome", "parent": null, "rules": [{"id": "#L5RGS27aB8cD0eF2gH4iJ6k", "text": "ref_quality_cumbersome \"Cumbersome: While wearing Cumbersome armor, increase TN of your other checks to maneuver in your environment (such as Movement action checks) by 1.\\n\\nIf you moved this turn, increase the TN of Attack action checks using a Cumbersome weapon by 1.\""}], "slot": null, "synthetic": true}, "u:a2655b3c8c278843": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:a2655b3c8c278843", "name": "Silhouettes Reference", "parent": null, "props": [{"dtype": "STRING", "name": "Silhouette 0", "value": "Handheld objects, cats, small dogs", "vk": "scalar"}, {"dtype": "STRING", "name": "Silhouette 1", "value": "Children, large dogs, goblins", "vk": "scalar"}, {"dtype": "STRING", "name": "Silhouette 2", "value": "Adult humans, ningyo, tengu", "vk": "scalar"}, {"dtype": "STRING", "name": "Silhouette 3", "value": "Horses, naga, rakshasa, Trolls", "vk": "scalar"}, {"dtype": "STRING", "name": "Silhouette 4", "value": "Ogres, elephants", "vk": "scalar"}, {"dtype": "STRING", "name": "Silhouette 5", "value": "Dragons", "vk": "scalar"}], "slot": null, "synthetic": true}, "u:afd51e0dc639b17b": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:afd51e0dc639b17b", "name": "Conflict Actions Reference", "parent": null, "rules": [{"id": "#L5RGS14nO5pQ7rS9tU1vW3x", "text": "ref_common_conflict_actions \"Common Conflict Actions: Assist\\n\\nCalming Breath\\n\\nChallenge\\n\\nGuard\\n\\nManeuver\\n\\nPrepare Item\\n\\nSkill Use\\n\\nStrike\\n\\nWait\""}], "slot": null, "synthetic": true}, "u:b5963f0d1583f44b": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:b5963f0d1583f44b", "name": "Item Quality: Ceremonial", "parent": null, "rules": [{"id": "#L5RGS26pQ7rS9tU1vW3xY5z", "text": "ref_quality_ceremonial \"Ceremonial: Reduce TN of checks to convince others of your real or assumed identity as the known owner of that item (or one of their allies) by 1.\\n\\nAt the end of any scene in which you use a Ceremonial item of a character with higher status without their permission, you forfeit 3 honor.\""}], "slot": null, "synthetic": true}, "u:b9d3096aa6fa952b": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:b9d3096aa6fa952b", "name": "Item Quality: Sacred", "parent": null, "rules": [{"id": "#L5RGS31sT2uV4wX6yZ8aB0c", "text": "ref_quality_sacred \"Sacred: When an Otherworldly being makes an Attack or Intrigue action check targeting the wearer of one or more Sacred items, increase the TN by 1.\\n\\nWhile carrying one or more Sacred items, if you would gain the Afflicted condition, must choose one of them to become Damaged instead.\\n\\nSacred weapons ignore all resistances possessed by Otherworldly and Tainted beings.\""}], "slot": null, "synthetic": true}, "u:cbd9a2033c967fda": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:cbd9a2033c967fda", "name": "Turn Structure Reference", "parent": null, "rules": [{"id": "#L5RGS04hI5jK7lM9nO1pQ3r", "text": "ref_turn_structure \"Turn Structure: 1. Resolve \\\"Beginning of Turn\\\" effects\\n\\n2. Set Stance (lasts until beginning of next turn)\\n\\n3. Perform Action (may also move a short distance)\\n\\n4. Resolve \\\"End of Turn\\\" effects\""}], "slot": null, "synthetic": true}, "u:cf6728b8518c8853": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:cf6728b8518c8853", "name": "Item Quality: Wargear", "parent": null, "rules": [{"id": "#L5RGS34zA5bC7dE9fG1hI3j", "text": "ref_quality_wargear \"Wargear: Whenever another character suffers 1 or more strife due to the actions of someone wearing one or more Wargear items, they suffer that amount plus 1 instead.\""}], "slot": null, "synthetic": true}, "u:eecc69c02dfcbdb0": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:eecc69c02dfcbdb0", "name": "Condition: Dazed", "parent": null, "rules": [{"id": "#L5RGS19qR0sT2uV4wX6yZ8a", "text": "ref_condition_dazed \"Dazed: Effects: Increase the TN of Attack and Scheme action checks by 2.\\n\\nRemoved When: At the end of turn, if the character did not perform an Attack or Scheme action.\""}], "slot": null, "synthetic": true}, "u:f043980538821102": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:f043980538821102", "name": "Stances Reference", "parent": null, "rules": [{"id": "#L5RGS05sT6uV8wX0yZ2aB4c", "text": "ref_stances_five_types \"Stances: Earth: When other characters make Attack action checks and Scheme action checks that target you, they cannot spend (op) to inflict critical strikes or conditions on you.\\n\\nWater: During your turn, you may perform one additional action that does not require a check. This action cannot share a type with another action you perform this turn.\\n\\nFire: When you succeed on a check, you count as having one additional bonus success for each (st) result on your check.\\n\\nAir: Increase the TN of Attack and Scheme action checks targeting you by 1. If your school rank is 4 or higher, increase the TN by 2 instead.\\n\\nVoid: While in a Void stance, you do not suffer strife from (st) results.\""}], "slot": null, "synthetic": true}, "u:f6b6c3b5b88d82b2": {"applies": [{"hash": "#t4bb5a837984a5a2879be0", "name": "Game Rules"}], "book": "gm-screen", "children": [], "file": "l5r5e-0.5-gm-screen-reference.ttrpg", "form": "DEF", "id": "u:f6b6c3b5b88d82b2", "name": "Dice Symbols Reference", "parent": null, "rules": [{"id": "#L5RGS01aB2cD4eF6gH8iJ0k", "text": "ref_dice_symbols \"Dice Symbols: The success symbol ((su)) represents the sum total of the character's effort when they attempt to complete a task. More (su) symbols mean a higher chance of carrying out the task successfully.\\n\\nThe explosive success symbol ((ex)) represents a particularly effective part of the character's effort. In addition to counting as a (su) symbol, it gives the character a chance to roll an additional die and decide whether to add its result to the check—potentially letting them succeed at a task they normally couldn't overcome. See (ex) under Step 6: Resolve Symbols of Kept Dice, on page 24.\\n\\nThe opportunity symbol ((op)) does not contribute directly to success, but it lets the character resolve an opportunity—a chance to do or notice something useful that is unrelated to their goal at the outset, or expand on their success with an additional effect or story detail.\\n\\nThe strife symbol ((st)) represents an upwelling of emotion. Strife does not affect success or failure on the check but instead accumulates over time, potentially leading to outward displays of emotion that can alter the direction of the story for good or for ill. The more it accumulates, the harder it is to maintain the decorum expected of a samurai—a key struggle in the genre of samurai drama.\""}], "slot": null, "synthetic": true}}, "src": "data/gm-screen.js"};var T=window.L5R5E=window.L5R5E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
